// toolsmith plugin for OpenCode — registers the skills directory, registers the
// toolsmith subagent, and injects bootstrap context into the first user message.
// GENERATED by everyharness — edit everyharness.yaml instead
//
// Dual-compatible with OpenCode V1 and V2:
//
//   V1 loads the named export `ToolsmithPlugin`: config hook for the skills
//   path, plus `experimental.chat.messages.transform` for the bootstrap.
//
//   V2 loads the default export `{ id, setup }`. setup() registers the skill
//   and the toolsmith agent through ctx transforms and injects the bootstrap
//   through the `context`, `compaction` and `generate` session hooks. V2
//   dispatches every request shape, so all three need the same prefix or the
//   prompt cache goes cold on the largest request of a session.
//
// No external dependencies, so the same file works on both hosts without
// installing @opencode/plugin.

import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))

// Minimal frontmatter stripper (dependency-free rather than pulling in a
// markdown/frontmatter package for the handful of files read here).
const extractAndStripFrontmatter = (content) => {
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/)
  if (!match) return { frontmatter: {}, content }

  const frontmatter = {}
  let lastKey = null
  for (const rawLine of match[1].split('\n')) {
    const line = rawLine.replace(/\r$/, '')
    const colonIdx = line.indexOf(':')
    if (colonIdx > 0 && !/^\s/.test(line)) {
      const key = line.slice(0, colonIdx).trim()
      const value = line.slice(colonIdx + 1).trim()
      // Block scalar markers carry no value themselves.
      frontmatter[key] = /^(>[+-]?|\|[+-]?)$/.test(value) ? '' : value
      lastKey = key
    } else if (lastKey !== null && line.trim() !== '') {
      frontmatter[lastKey] = `${frontmatter[lastKey]} ${line.trim()}`.trim()
    }
  }
  for (const key of Object.keys(frontmatter)) {
    frontmatter[key] = frontmatter[key].replace(/^(["'])([\s\S]*)\1$/, '$2')
  }
  return { frontmatter, content: match[2] }
}

const pluginRoot = path.resolve(__dirname, '../..')
const skillsDir = path.join(pluginRoot, 'skills')
const agentPath = path.join(pluginRoot, 'agents/toolsmith.md')
const bootstrapPath = path.join(pluginRoot, 'hooks/everyharness/bootstrap.md')
const BOOTSTRAP_MARKER = '<plugin-bootstrap plugin="toolsmith">'

// Module-level cache for the bootstrap. The file does not change during a
// session, so reading and parsing it once eliminates redundant fs work on
// every agent step.
let _bootstrapCache = undefined // undefined = not yet loaded, null = file missing

const getBootstrapContent = () => {
  if (_bootstrapCache !== undefined) return _bootstrapCache

  if (!fs.existsSync(bootstrapPath)) {
    _bootstrapCache = null
    return null
  }

  const { content } = extractAndStripFrontmatter(fs.readFileSync(bootstrapPath, 'utf8'))
  _bootstrapCache = BOOTSTRAP_MARKER + '\n' + content + '\n</plugin-bootstrap>'
  return _bootstrapCache
}

/**
 * V1 plugin function (named export, also reachable as default.server).
 */
export const ToolsmithPlugin = async () => {
  return {
    // Inject the plugin's skills path into the live config so OpenCode
    // discovers its skills without manual symlinks or config edits.
    config: async (config) => {
      // V2 hands plugins a flat skills array; setup() registers there.
      if (Array.isArray(config.skills)) return

      config.skills = config.skills || {}
      config.skills.paths = config.skills.paths || []
      if (!config.skills.paths.includes(skillsDir)) {
        config.skills.paths.push(skillsDir)
      }
    },

    // Inject bootstrap into the first user message, guarded by a marker
    // substring so re-running the transform on an already transformed
    // message array never injects twice.
    'experimental.chat.messages.transform': async (_input, output) => {
      const bootstrap = getBootstrapContent()
      if (!bootstrap || !output.messages.length) return
      const firstUser = output.messages.find((m) => m.info.role === 'user')
      if (!firstUser || !firstUser.parts.length) return

      if (firstUser.parts.some((p) => p.type === 'text' && p.text.includes(BOOTSTRAP_MARKER))) return

      const ref = firstUser.parts[0]
      firstUser.parts.unshift({ ...ref, type: 'text', text: bootstrap })
    },
  }
}

/**
 * V2 setup. A V1 host may also call it with a V1-shaped ctx; detect and
 * return quietly, because the named export already serves V1.
 */
const setup = async (ctx) => {
  if (!ctx?.skill?.transform || !ctx?.session?.hook) return

  // 1. Register the writing-tools skill.
  try {
    const skills = []
    if (fs.existsSync(skillsDir)) {
      for (const entry of fs.readdirSync(skillsDir, { withFileTypes: true })) {
        if (!entry.isDirectory() || entry.name.startsWith('.')) continue
        const skillPath = path.join(skillsDir, entry.name, 'SKILL.md')
        if (!fs.existsSync(skillPath)) continue
        const { frontmatter, content } = extractAndStripFrontmatter(fs.readFileSync(skillPath, 'utf8'))
        skills.push({
          id: entry.name,
          name: frontmatter.name || entry.name,
          ...(frontmatter.description ? { description: frontmatter.description } : {}),
          path: skillPath,
          content,
        })
      }
    }
    await ctx.skill.transform((draft) => {
      // A throw escaping the callback hard-disables the plugin, so contain
      // failures per skill.
      for (const skill of skills) {
        try {
          draft.add(skill)
        } catch (err) {
          console.error(`[toolsmith] skill "${skill.id}" rejected by host, skipping:`, err)
        }
      }
    })
  } catch (err) {
    console.error('[toolsmith] skill registration failed:', err)
  }

  // 2. Register the toolsmith subagent, with CLAUDE_PLUGIN_ROOT resolved to
  // the real plugin checkout so the references are readable.
  //
  // The agent editor in 2.3.x has list/get/default/update/remove but no
  // `add` (the docs still describe one), and update() on an unknown id
  // creates the agent, so that is the path used here.
  try {
    if (fs.existsSync(agentPath)) {
      const { frontmatter, content } = extractAndStripFrontmatter(fs.readFileSync(agentPath, 'utf8'))
      const system = content.replaceAll('${CLAUDE_PLUGIN_ROOT}', pluginRoot)
      const definition = {
        id: 'toolsmith',
        name: 'toolsmith',
        description: frontmatter.description,
        mode: 'subagent',
        hidden: false,
        system,
        request: { settings: {}, headers: {}, body: {} },
        permissions: [{ action: '*', resource: '*', effect: 'allow' }],
      }
      await ctx.agent.transform((draft) => {
        try {
          draft.update('toolsmith', (agent) => Object.assign(agent, definition))
        } catch (err) {
          console.error('[toolsmith] agent registration rejected by host:', err)
        }
      })
    }
  } catch (err) {
    console.error('[toolsmith] agent registration failed:', err)
  }

  // 3. Inject the bootstrap into the first user message of each request.
  const injectBootstrap = async (event) => {
    try {
      const bootstrap = getBootstrapContent()
      if (!bootstrap || !event.messages?.length) return
      const firstUser = event.messages.find((m) => m.role === 'user')
      if (firstUser && !firstUser.content?.length) return
      if (firstUser?.content.some((p) => p.type === 'text' && p.text?.includes(BOOTSTRAP_MARKER))) return

      // Native compaction can leave only an opaque checkpoint; keep it and
      // append the transient bootstrap as a user message.
      if (firstUser) {
        firstUser.content.unshift({ type: 'text', text: bootstrap })
      } else {
        event.messages.push({ role: 'user', content: [{ type: 'text', text: bootstrap }] })
      }
    } catch (err) {
      console.error('[toolsmith] session hook failed:', err)
    }
  }

  for (const hookName of ['context', 'compaction', 'generate']) {
    try {
      await ctx.session.hook(hookName, injectBootstrap)
    } catch (err) {
      console.error(`[toolsmith] session hook registration failed (${hookName}):`, err)
    }
  }
}

export default {
  id: 'toolsmith',
  server: ToolsmithPlugin,
  setup,
}
